def charge(Q0,R,C,dt,T):
    Q=Q0; out=[Q]; k=1/(R*C)
    for _ in range(round(T/dt)):
        a=-k*Q; b=-k*(Q+dt/2*a); c=-k*(Q+dt/2*b); d=-k*(Q+dt*c)
        Q+=dt/6*(a+2*b+2*c+d); out.append(Q)
    return out

