import math
def period(t0,L,g):
    th=math.radians(t0); w=0.0; t=0.0; dt=1e-4
    f=lambda th,w:(w,-g/L*math.sin(th))
    while True:
        k1=f(th,w);k2=f(th+dt/2*k1[0],w+dt/2*k1[1]);k3=f(th+dt/2*k2[0],w+dt/2*k2[1]);k4=f(th+dt*k3[0],w+dt*k3[1])
        nth=th+dt/6*(k1[0]+2*k2[0]+2*k3[0]+k4[0]); nw=w+dt/6*(k1[1]+2*k2[1]+2*k3[1]+k4[1])
        if nth<=0: return 4*(t+dt*th/(th-nth))
        th,w,t=nth,nw,t+dt

