import random
def msd(n,steps,seed):
    rng=random.Random(seed); xs=[0]*n; ys=[0]*n; out=[0.0]
    mv=[(1,0),(-1,0),(0,1),(0,-1)]
    for _ in range(steps):
        s=0
        for i in range(n):
            dx,dy=mv[rng.randrange(4)]; xs[i]+=dx; ys[i]+=dy; s+=xs[i]*xs[i]+ys[i]*ys[i]
        out.append(s/n)
    return out

