import math
def heat(N,alpha,dt,steps):
    dx=1/N; r=alpha*dt/dx/dx; u=[math.sin(math.pi*j*dx) for j in range(N+1)]
    for _ in range(steps):
        u=[0.0]+[u[j]+r*(u[j+1]-2*u[j]+u[j-1]) for j in range(1,N)]+[0.0]
    return u
